def transform(grid):
    h, w = len(grid), len(grid[0])
    split = None

    # Find a uniform divider that separates two equal-sized panels.
    for c in range(1, w - 1):
        if w - c - 1 == c and all(row[c] == grid[0][c] for row in grid):
            split = ("v", c)
            break
    if split is None:
        for r in range(1, h - 1):
            if h - r - 1 == r and all(x == grid[r][0] for x in grid[r]):
                split = ("h", r)
                break

    if split[0] == "v":
        c = split[1]
        a = [row[:c] for row in grid]
        b = [row[c + 1:] for row in grid]
    else:
        r = split[1]
        a = grid[:r]
        b = grid[r + 1:]

    from collections import Counter
    background = Counter(x for row in a for x in row).most_common(1)[0][0]
    return [
        [3 if a[i][j] == b[i][j] else background for j in range(len(a[0]))]
        for i in range(len(a))
    ]
